  const fire = (e, type, target) => (e.listeners[type] || []).forEach(fn => fn({ target }));
  return {
    titles, ids,
    addTask(t) { els.title.value = t; fire(els.add, "click", els.add); },
    setFilter(v) { els.filter.value = v; fire(els.filter, "change", els.filter); },
